import{_ as t,a as o,o as s,a6 as a}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse(`{"title":"Customer Logout","description":"","frontmatter":{"outline":false,"examples":[{"id":"customer-logout","title":"Customer Logout","description":"End the customer's authenticated session.","request":"POST /api/shop/customer/logout\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\n","response":"{\\n  \\"message\\": \\"Successfully logged out\\"\\n}\\n","commonErrors":[{"error":"401 Unauthorized","cause":"Customer not authenticated","solution":"Only authenticated customers can logout"},{"error":"400 Bad Request","cause":"Invalid logout request","solution":"Ensure Bearer token is provided"}]}]},"headers":[],"relativePath":"api/rest-api/shop/customers/customer-logout.md","filePath":"api/rest-api/shop/customers/customer-logout.md","lastUpdated":1786429091000}`),r={name:"api/rest-api/shop/customers/customer-logout.md"};function i(n,e,l,d,c,u){return s(),o("div",null,e[0]||(e[0]=[a('<h1 id="customer-logout" tabindex="-1">Customer Logout <a class="header-anchor" href="#customer-logout" aria-label="Permalink to &quot;Customer Logout&quot;">​</a></h1><p>End the customer&#39;s authenticated session and invalidate their token.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/shop/customer/logout</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Bearer token (customer login required)</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request Body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request Body&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{}</span></span></code></pre></div><p>No body parameters required.</p><h2 id="response-fields-200-ok" tabindex="-1">Response Fields (200 OK) <a class="header-anchor" href="#response-fields-200-ok" aria-label="Permalink to &quot;Response Fields (200 OK)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>message</code></td><td>string</td><td>Success message</td></tr></tbody></table><h2 id="after-logout" tabindex="-1">After Logout <a class="header-anchor" href="#after-logout" aria-label="Permalink to &quot;After Logout&quot;">​</a></h2><p>Only the token used on the request is revoked. Other tokens the same customer holds — a second device, another browser — keep working, so logging out on a phone does not sign the shopper out on their laptop.</p><ul><li>The token used here answers <code>401</code> on every later request and cannot be revived.</li><li>The customer&#39;s cart, wishlist, and compare list are untouched and are still there at the next login.</li><li>Any device token registered for push notifications is cleared as part of the call.</li></ul><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Sign out on one device</strong> — call with that device&#39;s token and discard it locally; other sessions stay live.</li><li><strong>Sign out everywhere</strong> — the API revokes one token per call, so a &quot;log out of all devices&quot; control has to call once per stored token, or the account has to be re-authenticated.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Discard the token client-side even if the call fails</strong> — a token the server already dropped answers <code>401</code> here too, and the shopper still expects to be signed out.</li><li><strong>Do not use logout to clear a cart</strong> — the cart survives; remove the items explicitly if the flow needs an empty cart.</li><li><strong>Re-authenticate rather than looping tokens for a global sign-out</strong> — the endpoint has no all-sessions mode.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/customers/customer-login.html">Customer Login</a> — authenticate and receive a customer token</li><li><a href="/api/rest-api/shop/customers/customer-registration.html">Customer Registration</a> — create an account and receive a token</li><li><a href="/api/rest-api/shop/customers/customer-verify-token.html">Verify Customer Token</a> — check whether a stored token still resolves</li></ul>',20)]))}const m=t(r,[["render",i]]);export{p as __pageData,m as default};
